class DBConn:
    def __init__(self, raw, postgres=False):
        self.raw = raw
        self.postgres = postgres

    def execute(self, sql, params=()):
        if self.postgres:
            return self.raw.execute(sql.replace("?", "%s"), params)
        return self.raw.execute(sql, params)

    def executemany(self, sql, seq):
        if self.postgres:
            return self.raw.executemany(sql.replace("?", "%s"), seq)
        return self.raw.executemany(sql, seq)

    def executescript(self, sql):
        if self.postgres:
            for stmt in [s.strip() for s in sql.split(";") if s.strip()]:
                stmt = stmt.replace(
                    "INTEGER PRIMARY KEY AUTOINCREMENT",
                    "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
                )
                self.raw.execute(stmt)
        else:
            self.raw.executescript(sql)

    def commit(self):
        self.raw.commit()

    def close(self):
        self.raw.close()


def conn():
    if USE_POSTGRES:
        if psycopg is None:
            raise RuntimeError("psycopg fehlt")
        raw = psycopg.connect(DATABASE_URL, row_factory=dict_row)
        return DBConn(raw, postgres=True)
    raw = sqlite3.connect(DB, timeout=30, check_same_thread=False)
    raw.row_factory = sqlite3.Row
    raw.execute("PRAGMA journal_mode=WAL")
    raw.execute("PRAGMA busy_timeout=30000")
    return DBConn(raw, postgres=False)


