def legacy_step(status, step):
    if status == "Transport abgeschlossen":
        return 6
    mapping = {
        "Offen": 0,
        "Angefragt": 0,
        "Disposition": 0,
        "Bestätigt": 1,
        "Unterwegs": 2,
        "Fahrer unterwegs": 2,
        "Patient abgeholt": 3,
        "Unterwegs zum Ziel": 4,
        "Angekommen": 5,
        "Abgeschlossen": 6,
    }
    try:
        step = int(step or 0)
    except Exception:
        step = 0
    return max(0, min(6, mapping.get(status, step)))


def haversine_km(lat1, lon1, lat2, lon2):
    try:
        lat1, lon1, lat2, lon2 = map(float, (lat1, lon1, lat2, lon2))
    except (TypeError, ValueError):
        return None
    r = 6371.0088
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dl = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * r * math.asin(math.sqrt(a))


def is_driver_free(c, driver_id):
    row = c.execute(
        "SELECT COUNT(*) AS n FROM requests WHERE assigned_driver_id=? AND status_step < 6",
        (driver_id,),
    ).fetchone()
    return int(row["n"] or 0) == 0


def get_driver_rows(c):
    return c.execute(
        """
        SELECT u.id,u.username,u.name,u.active,u.availability,u.hospital_name,u.station_name,
               dl.latitude,dl.longitude,dl.updated_at
        FROM users u
        LEFT JOIN driver_locations dl ON dl.driver_id=u.id
        WHERE u.role='driver'
        ORDER BY u.name
        """
    ).fetchall()


def get_driver_capabilities(c, driver_id):
    rows = c.execute("SELECT transport_type FROM driver_capabilities WHERE driver_id=? AND active=1", (driver_id,)).fetchall()
    return {r["transport_type"] for r in rows}


def driver_can_take(capabilities, transport_type):
    """Hierarchical Fahrer-Rechte: LIEGE kann alle, ROLLSTUHL kann Rollstuhl + Sitzend, NORMAL nur Sitzend."""
    caps = {str(x or '').upper() for x in (capabilities or set())}
    t = str(transport_type or '').strip().upper()
    if 'LIEGE' in caps:
        return t in {'SITZEND', 'ROLLSTUHL', 'LIEGEND', 'AMBULANZ'}
    if 'ROLLSTUHL' in caps:
        return t in {'SITZEND', 'ROLLSTUHL'}
    if 'NORMAL' in caps:
        return t == 'SITZEND'
    return False


def get_free_drivers(c, pickup_lat=None, pickup_lng=None, transport_type="Sitzend"):
    required = required_capability(transport_type)
    rows = [
        r for r in get_driver_rows(c)
        if int(r["active"] or 0) == 1
        and r["availability"] != "OFFLINE"
        and is_driver_free(c, r["id"])
        and driver_can_take(get_driver_capabilities(c, r["id"]), transport_type)
    ]
    enriched = []
    for r in rows:
        d = dict(r)
        d["capabilities"] = sorted(get_driver_capabilities(c, r["id"]))
        d["distance_km"] = haversine_km(pickup_lat, pickup_lng, r["latitude"], r["longitude"]) if pickup_lat is not None and pickup_lng is not None and r["latitude"] is not None and r["longitude"] is not None else None
        enriched.append(d)
    enriched.sort(key=lambda x: (x["distance_km"] is None, x["distance_km"] if x["distance_km"] is not None else 1e9, x["name"]))
    return enriched


def next_order_code(c):
    row = c.execute("SELECT next_number FROM order_counter WHERE id=1").fetchone()
    number = int(row["next_number"] or 1) if row else 1
    return f"AU{number:06d}"


def allocate_order_number(c):
    if USE_POSTGRES:
        row = c.execute("SELECT next_number FROM order_counter WHERE id=1 FOR UPDATE").fetchone()
    else:
        try:
            c.raw.execute("BEGIN IMMEDIATE")
        except sqlite3.OperationalError:
            pass
        row = c.execute("SELECT next_number FROM order_counter WHERE id=1").fetchone()
    if not row:
        c.execute("INSERT INTO order_counter(id,next_number) VALUES(1,2)")
        return "AU000001"
    number = int(row["next_number"])
    c.execute("UPDATE order_counter SET next_number=? WHERE id=1", (number + 1,))
    return f"AU{number:06d}"


def auth(roles=None):
    """Validate the current session and repair stale role values from the database.

    Older deployments used the legacy role name ``dispatch``. A browser session can
    survive a deploy, so relying only on the role stored in the cookie could make a
    valid user appear unauthorized until logout/login. We therefore re-read the
    authoritative role for the session user when needed.
    """
    uid = session.get("user_id")
    if not uid:
        return False

    role = session.get("role")
    if role not in ROLES:
        try:
            c = conn()
            u = c.execute("SELECT id,username,name,role,active FROM users WHERE id=?", (uid,)).fetchone()
            c.close()
            if not u or int(u["active"] or 0) != 1 or u["role"] not in ROLES:
                session.clear()
                return False
            session.update(user_id=u["id"], username=u["username"], name=u["name"], role=u["role"])
            role = u["role"]
        except Exception:
            return False

    return roles is None or role in roles


def require_roles(*roles):
    def deco(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            if not auth(roles):
                abort(403)
            return fn(*args, **kwargs)
        return wrapper
    return deco

def audit(c, action, user_id=None):
    try:
        c.execute("INSERT INTO audit_log(user_id,action) VALUES(?,?)", (user_id or session.get("user_id"), action))
    except Exception as e:
        print("Audit warning:", e)


def ensure_hospital_station(c, hospital_name, station_name):
    """Register a hospital/station pair so Production can scale beyond the demo users."""
    if not hospital_name or not station_name:
        return
    h = c.execute("SELECT id FROM hospitals WHERE name=?", (hospital_name,)).fetchone()
    if h:
        hospital_id = h["id"]
    else:
        c.execute("INSERT INTO hospitals(name,active) VALUES(?,1)", (hospital_name,))
        hospital_id = c.execute("SELECT id FROM hospitals WHERE name=?", (hospital_name,)).fetchone()["id"]
    if not c.execute("SELECT id FROM stations WHERE hospital_id=? AND name=?", (hospital_id, station_name)).fetchone():
        code = ("".join(ch for ch in station_name.upper() if ch.isalnum())[:8] or "STATION")
        c.execute("INSERT INTO stations(hospital_id,name,code,active) VALUES(?,?,?,1)", (hospital_id, station_name, code))


