TEST_EMAIL_RECIPIENT = os.environ.get("TEST_EMAIL_RECIPIENT", "eraldo.baca@gmail.com")
# V11: Email delivery uses Resend over HTTPS so it works on Render Free.
# SMTP variables remain supported as a fallback for paid/non-Render environments.
RESEND_API_KEY = os.environ.get("RESEND_API_KEY", "").strip()
RESEND_FROM_EMAIL = os.environ.get("RESEND_FROM_EMAIL", "onboarding@resend.dev").strip()
RESEND_API_URL = os.environ.get("RESEND_API_URL", "https://api.resend.com/emails").strip()
EMAIL_PROVIDER = os.environ.get("EMAIL_PROVIDER", "resend").strip().lower()

SMTP_HOST = os.environ.get("SMTP_HOST", "smtp.gmail.com")
SMTP_PORT = int(os.environ.get("SMTP_PORT", "587"))
SMTP_USER = os.environ.get("SMTP_USER", "")
SMTP_PASSWORD = os.environ.get("SMTP_PASSWORD", "")
SMTP_FROM = os.environ.get("SMTP_FROM", SMTP_USER or TEST_EMAIL_RECIPIENT)
SMTP_USE_TLS = os.environ.get("SMTP_USE_TLS", "1") == "1"
EMAIL_NOTIFICATIONS_ENABLED = os.environ.get("EMAIL_NOTIFICATIONS_ENABLED", "1") == "1"
EMAIL_TEST_MODE = os.environ.get("EMAIL_TEST_MODE", "1") == "1"
PUSH_NOTIFICATIONS_ENABLED = os.environ.get("PUSH_NOTIFICATIONS_ENABLED", "1") == "1"
