@app.route("/", methods=["GET", "POST"])
def login():
    """Login page. Keeps the existing application/session logic intact."""
    if request.method == "GET":
        if auth():
            return redirect("/dashboard")
        return render_template_string(LOGIN, error=None)

    username = (request.form.get("username") or "").strip()
    password = request.form.get("password") or ""
    c = conn()
    u = c.execute(
        "SELECT id,username,name,role,active,password_hash FROM users WHERE username=?",
        (username,),
    ).fetchone()

    ok = bool(
        u
        and int(u["active"] or 0) == 1
        and u["role"] in ROLES
        and check_password_hash(u["password_hash"], password)
    )

    try:
        c.execute(
            "INSERT INTO login_attempts(username,ip_address,succeeded) VALUES(?,?,?)",
            (username, request.headers.get("X-Forwarded-For", request.remote_addr or ""), 1 if ok else 0),
        )
        c.commit()
    except Exception:
        pass
    c.close()

    if not ok:
        return render_template_string(LOGIN, error="Benutzername oder Passwort ist nicht korrekt."), 401

    session.clear()
    session.update(
        user_id=u["id"],
        username=u["username"],
        name=u["name"],
        role=u["role"],
    )
    return redirect("/dashboard")


