@app.post("/request/<int:i>/problem")
@require_roles("admin", "hospital", "driver")
def report_problem(i):
    import urllib.parse
    c=conn(); r=c.execute("SELECT * FROM requests WHERE id=?",(i,)).fetchone()
    if not r: c.close(); abort(404)
    if session["role"]=="hospital":
        u=c.execute("SELECT hospital_name,station_name FROM users WHERE id=?",(session["user_id"],)).fetchone()
        if r["hospital_name"]!=u["hospital_name"] or r["station_name"]!=u["station_name"]: c.close(); abort(403)
    if session["role"]=="driver" and r["assigned_driver_id"]!=session["user_id"]: c.close(); abort(403)
