@app.post("/user")
@require_roles("admin")
def new_user():
    import urllib.parse
    name=request.form.get("name","").strip(); username=request.form.get("username","").strip(); password=request.form.get("password",""); role=request.form.get("role","hospital"); hospital=request.form.get("hospital_name","").strip(); station=request.form.get("station_name","").strip(); driver_capability=(request.form.get("driver_capability") or "").strip().upper()
    if role not in ROLES or not name or not username or not password: abort(400)
    if role == "hospital" and (not hospital or not station): return redirect("/dashboard?msg="+urllib.parse.quote("Bei Station-Benutzern müssen Krankenhaus und Station ausgefüllt sein."))
    if role != "hospital":
        hospital = hospital or "Transportteam"
        station = station or ("Administration" if role=="admin" else "Fahrer")
    c=conn()
    try:
        if role == "hospital":
            ensure_hospital_station(c, hospital, station)
        cur=c.execute("INSERT INTO users(username,password_hash,name,role,active,hospital_name,station_name,availability) VALUES(?,?,?,?,1,?,?,?)",(username,generate_password_hash(password),name,role,hospital,station,"AVAILABLE"))
        uid = cur.lastrowid if not USE_POSTGRES else c.execute("SELECT id FROM users WHERE username=?",(username,)).fetchone()["id"]
        if role == "driver" and driver_capability in DRIVER_CAPABILITIES:
            c.execute("INSERT INTO driver_capabilities(driver_id,transport_type,active) VALUES(?,?,1)",(uid,driver_capability))
        audit(c,f"Benutzer {username} angelegt"); c.commit()
    except Exception:
        try: c.raw.rollback()
        except Exception: pass
        c.close(); return redirect("/dashboard?msg="+urllib.parse.quote("Benutzername existiert bereits oder ist ungültig."))
    c.close(); return redirect("/dashboard?msg="+urllib.parse.quote("Benutzer erfolgreich angelegt."))


@app.route("/familie/<family_code>")
def family_view(family_code):
    c=conn(); r=c.execute("SELECT r.*,u.name AS driver_name FROM requests r LEFT JOIN users u ON u.id=r.assigned_driver_id WHERE r.family_code=?",(family_code,)).fetchone()
    if not r: c.close(); abort(404)
    history=c.execute("SELECT status,step,changed_by,created_at FROM status_history WHERE request_id=? ORDER BY id ASC",(r["id"],)).fetchall(); c.close()
    history_by_step={}
    for h in history: history_by_step.setdefault(int(h["step"]),[]).append(h)
    return render_template_string(FAMILY,r=r,steps=STATUS_STEPS,history_by_step=history_by_step)


