    if not driver: c.close(); abort(404)
    rows=c.execute("SELECT * FROM requests WHERE assigned_driver_id=? ORDER BY id DESC",(driver_id,)).fetchall(); total=len(rows); done=sum(1 for r in rows if int(r["status_step"] or 0)==6); c.close()
