@app.get("/rechnung/<int:invoice_id>")
@require_roles("admin", "dispatcher")
def view_invoice(invoice_id):
    c=conn(); ensure_abrechnung_schema(c)
    inv=c.execute("SELECT i.*,bc.request_id,bc.payer_type,bc.payer_name,bc.insurance_number,bc.billing_address,bc.email,r.code,r.patient_id,r.pickup,r.destination,r.requested_time,r.transport_type,r.hospital_name,r.station_name,u.name AS driver_name FROM invoices i JOIN billing_cases bc ON bc.id=i.billing_case_id JOIN requests r ON r.id=bc.request_id LEFT JOIN users u ON u.id=r.assigned_driver_id WHERE i.id=?",(invoice_id,)).fetchone()
    items=c.execute("SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY id",(invoice_id,)).fetchall()
    c.close()
    if not inv: abort(404)
    html=f"""
    <!doctype html><html lang=de><head><meta charset=utf-8><title>{inv['invoice_number']}</title>
    <style>body{{font-family:Arial,sans-serif;background:#f4f7f6;margin:0;color:#173c34}}.sheet{{max-width:860px;margin:30px auto;background:#fff;padding:42px 48px 34px;border-radius:18px;box-shadow:0 10px 35px rgba(0,0,0,.08)}}h1{{margin:0 0 6px}}.muted{{color:#70857f}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:28px 0}}table{{width:100%;border-collapse:collapse;margin-top:22px}}th,td{{padding:11px;border-bottom:1px solid #e4ece9;text-align:left}}.total{{font-size:20px;font-weight:900;text-align:right;margin-top:24px}}.print{{float:right;padding:10px 16px;border:0;border-radius:10px;background:#117d6d;color:white;font-weight:700}}@media print{{body{{background:white}}.sheet{{box-shadow:none;margin:0;max-width:none}}.print{{display:none}}}}</style></head><body>
    <div class=sheet><button class=print onclick="window.print()">Drucken / PDF speichern</button><div class=muted>ENTLASS-CONNECT · Abrechnung</div><h1>Rechnung {inv['invoice_number']}</h1><div class=muted>Status: {inv['status']}</div>
    <div class=grid><div><b>Rechnungsempfänger</b><br>{inv['payer_name'] or inv['payer_type']}<br>Versichertennummer: {inv['insurance_number'] or '—'}</div><div><b>Patient</b><br>{inv['patient_id'] or '—'}<br>Fahrt: {inv['requested_time'] or '—'}</div></div>
    <table><tr><th>Leistung</th><th>Entfernung</th><th>Einzelpreis</th><th>Betrag</th></tr>
    {''.join(f"<tr><td>{it['description']}</td><td>{it['quantity']:.1f} km</td><td>{it['unit_price']:.2f} €</td><td>{it['amount']:.2f} €</td></tr>" for it in items)}
    </table><div class=grid><div><b>Abholort</b><br>{inv['pickup']}<br><br><b>Ziel</b><br>{inv['destination']}</div><div><b>Tarif</b><br>{inv['tariff_name'] or 'Demo-Tarif'}<br><br><b>Fahrer</b><br>{inv['driver_name'] or '—'}</div></div>
    <div class=total>Fahrpreis: {inv['fare_amount'] or inv['gross_amount']:.2f} €<br>Zuzahlung: {inv['copayment'] or 0:.2f} €<br>Kassenanteil: {inv['payer_amount'] if inv['payer_amount'] is not None else (inv['gross_amount'] or 0):.2f} €</div>
    <p class=muted style="margin-top:28px">Hinweis: Demo-Tarif zur Systemerprobung. Vor produktiver Abrechnung sind die vertraglich gültigen Kassen-/Tarifkennzeichen und Vergütungssätze des jeweiligen Kostenträgers zu hinterlegen.</p></div></body></html>"""
    return html

